const h={ui:{fig:"Fig. 5",title:"Lapped zipper",svgLabel:"An isometric drawing of how a lapped zipper is sewn into a seam: the seam sewn up to the mark at the bottom stop with a backstitch, the opening basted with the longest stitch and the seam pressed open; on the underlap side the seam allowance folded out and the zipper stitched to it face down, close to the teeth; the zipper turned face up, so a fold a little narrower than the allowance forms by the teeth, and stitched along that fold through the allowance and the zipper tape; the overlap folded on the seam line over the zipper, covering both those stitchings; stitched with the zipper foot along the overlap side and across the bottom, clear of the teeth and the pull; then the basting unpicked. One line of stitching shows.",prev:"Previous step",dot:(e,t)=>e?`Step ${e}: ${t}`:t,start:"Steps →",next:"Next →",overview:"Overview",stepOf:(e,t)=>`Step ${e} of ${t}`,machine:e=>`Machine: ${e.toLowerCase()}`,inThisStep:"In this step",takeApart:"See through the fabric",putTogether:"Back to the fabric",replay:"↻ Replay",parts:"Parts",allSteps:"Step-by-step instructions",endView:"END VIEW"},stitches:{straight:"Straight stitch",basting:"Longest stitch"},labels:{rightSides:"right sides together",markStop:"mark the bottom stop",toMark:"the seam, up to the mark",backstitch:"backstitch",baste:"baste: the longest stitch",openOut:"open out",wrongUp:"wrong side up",pressOpen:"press the seam open",rightUp:"right side up",foldBack:"fold the overlap back",foldOut:"fold the allowance out",faceDown:"zipper face down",teethBySeam:"teeth by the seam line",nearTeeth:"stitch close to the teeth",allowanceOnly:"allowance and tape only",faceUp:"zipper face up",besideTeeth:"a fold by the teeth",narrower:"a little narrower than the allowance",alongFold:"stitch along the fold",overlapBack:"the overlap back over",covers:"it covers the stitching",belowStop:"across, below the stop",pivot:"pivot, needle down",clearTeeth:"clear of the teeth and the pull",unpick:"unpick the basting",oneLine:"one line of stitching shows"},steps:[{title:"Lapped zipper",text:"One side of the seam, the overlap, covers the zipper: its folded edge lies on the seam line, and one line of stitching shows, along that side and across the bottom. Tap to see through the fabric."},{title:"Right sides together",text:"Place the two pieces right sides together. Lay the zipper along the seam line and mark where its bottom stop is: the opening for the zipper ends at the mark.",details:["Finish the raw edges of the seam first, so they do not fray.","Place the two pieces right sides together, the edges even, and clip them.","Lay the zipper along the seam line and mark the seam line at its bottom stop: the opening for the zipper ends at the mark."]},{title:"The seam, up to the mark",text:"Sew the seam with a regular stitch up to the mark and backstitch there, so the seam holds where the zipper ends.",details:["Sew the seam with a regular stitch, on the seam line, up to the mark.","Backstitch at the mark: the seam must not come undone where the zipper ends."]},{title:"Baste the opening",text:"Set the longest stitch and sew the opening closed on the same seam line, between the mark and the top edge. This basting comes out at the end.",details:["Set the machine to its longest stitch: this is basting, it will be unpicked later.","Sew the opening closed on the same seam line, between the mark and the top edge.","The basting keeps both sides of the opening on the seam line while the zipper is sewn in."]},{title:"Press the seam open",text:"Open the pieces out, turn them wrong side up and press the seam allowances open, one to each side, along the whole seam.",details:["Open the pieces out and turn them wrong side up.","Press the seam allowances open, one to each side, along the whole seam, the basted part too."]},{title:"Fold the overlap back",text:"Turn the work right side up. One side of the opening, the overlap, will cover the zipper; the other, the underlap, goes under it. Fold the overlap back, out of the way: the basting holds it on the seam line.",details:["Turn the work right side up.","Choose the overlap: the side that will cover the zipper. The other side is the underlap.","Fold the overlap back over the underlap, out of the way, so it is not caught in the next stitching."]},{title:"The zipper face down",text:"On the underlap side, fold the seam allowance out, flat past the seam line. Lay the zipper face down on it, the teeth by the seam line, and pin it to this allowance.",details:["Fold the underlap's seam allowance out, so it lies flat past the seam line: only this allowance is under the zipper.","Lay the zipper face down on the allowance, the teeth by the seam line, the bottom stop at the mark.","Pin the zipper tape to the allowance."]},{title:"Stitch close to the teeth",text:"With the zipper foot, stitch the zipper tape to the seam allowance close to the teeth, through the tape and the allowance only, the whole length of the zipper but never over the bottom stop.",details:["Put on the zipper foot: it lets the needle stitch close to the zipper.","Stitch close to the teeth, through the zipper tape and the seam allowance only.","Stitch the whole length of the zipper, but never over the bottom stop."]},{title:"Turn the zipper face up",text:"Turn the zipper face up: the seam allowance folds under it, and a small fold forms right by the teeth, a little narrower than the seam allowance. Press the fold.",details:["Turn the zipper face up: the seam allowance folds under the zipper.","A small fold forms right beside the teeth, just past the seam line: the folded part is a little narrower than the seam allowance.","Press the fold."]},{title:"Stitch along the fold",text:"With the zipper foot, stitch close to the fold, through the seam allowance and the zipper tape only, the whole length of the zipper but never over the bottom stop.",details:["Stitch close to the fold, through the seam allowance and the zipper tape only: the overlap stays folded back.","Stitch the whole length of the zipper, but never over the bottom stop."]},{title:"The overlap over the zipper",text:"Bring the overlap back over the zipper, its folded edge on the seam line: it covers the teeth and both lines of stitching on the underlap. Pin it through all the layers.",details:["Bring the overlap back over the zipper: the basting keeps its folded edge on the seam line.","The overlap covers the teeth and both lines of stitching on the underlap.","Pin the overlap to the zipper tape under it, through all the layers."]},{title:"Stitch the overlap",text:"With the zipper foot, stitch the overlap side and across the bottom, below the stop, pivoting at the corner with the needle down, through all the layers. Keep the stitching wide enough to clear the teeth and the pull.",details:["Stitch along the overlap side and across the bottom, below the stop, through all the layers: wide enough to clear the teeth and the pull.","At the corner, stop with the needle down in the fabric, lift the foot, turn the work and go on.","Do not stitch over the stop."]},{title:"Unpick the basting",text:"Unpick the basting over the zipper and press. The overlap stays over the zipper, and one line of stitching shows.",details:["Unpick the basting stitches over the zipper.","Press from the right side: the overlap covers the zipper, and only its own line of stitching shows."]}],legend:[{title:"Fabric",text:"two pieces joined by one seam · the overlap's folded edge on the seam line"},{title:"Stitching",text:"one line: along the overlap side and across the bottom, below the stop"},{title:"Seam",text:"below the zipper, backstitched at the mark"},{title:"Zipper",text:"under the overlap, stitched twice to the underlap's allowance"}]};export{h as default};
